/* eslint-disable no-console */
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join, relative } from "node:path";

/**
 * ===========================================================================
 * AUDYT CZYSTOŚCI REPOZYTORIUM (`npm run audit:clean`)
 * ===========================================================================
 * Skanuje kod, konfigurację i dokumentację pod kątem markerów pochodzenia
 * treści (nazwy modeli, „generated by AI”, pozostałości promptów) oraz
 * zabłądzonych adresów z poprzednich środowisk.
 *
 * Kod wyjścia 1 = repozytorium nie jest gotowe do wdrożenia.
 */

const ROOTS = ["src", "scripts", "README.md", "package.json", "next.config.ts", "tsconfig.json"];
const EXTENSIONS = new Set([".ts", ".tsx", ".js", ".mjs", ".cjs", ".json", ".md", ".css", ".example"]);
const SKIP_DIRS = new Set(["node_modules", ".next", ".git", "out", "build"]);
/** Skrypt audytu zawiera wzorce w kodzie – nie może skanować sam siebie. */
const SKIP_FILES = new Set(["scripts/audit-clean.mjs"]);

/** Wzorce są case-insensitive; każdy ma czytelną etykietę do raportu. */
const RULES = [
  { label: "nazwa modelu", pattern: /deepseek/gi },
  { label: "pochodzenie AI", pattern: /ai[-\s]?generated|generated by ai/gi },
  { label: "chatbot", pattern: /chatgpt|openai|copilot|claude|gemini/gi },
  { label: "model językowy", pattern: /\bllms?\b|\bprompt(s|ed|ing)?\b/gi },
  { label: "polski marker AI", pattern: /wygenerowane przez (ai|model)|asystent ai/gi },
  {
    label: "pozostałość rozmowy",
    pattern:
      /w poprzedniej sesji|jak ustaliliśmy|zgodnie z instrukcj|użytkownik poprosił|as requested by the user|per the instructions/gi,
  },
  { label: "stara domena", pattern: /szybkikupiec|costainvest\.pl/gi },
];

const findings = [];
let scanned = 0;

function walk(path) {
  let stats;
  try {
    stats = statSync(path);
  } catch {
    return; // Ścieżka nie istnieje w tym wariancie repo – pomijamy.
  }

  if (stats.isDirectory()) {
    const name = path.split(/[\\/]/).pop() ?? "";
    if (SKIP_DIRS.has(name)) return;
    for (const child of readdirSync(path)) walk(join(path, child));
    return;
  }

  const extension = path.slice(path.lastIndexOf("."));
  if (!EXTENSIONS.has(extension)) return;

  const relativePath = relative(process.cwd(), path).split("\\").join("/");
  if (SKIP_FILES.has(relativePath)) return;

  scanned += 1;
  const lines = readFileSync(path, "utf8").split(/\r?\n/);
  lines.forEach((line, index) => {
    for (const rule of RULES) {
      rule.pattern.lastIndex = 0;
      const match = rule.pattern.exec(line);
      if (match) {
        findings.push({
          file: relativePath,
          line: index + 1,
          label: rule.label,
          match: match[0],
        });
      }
    }
  });
}

for (const root of ROOTS) walk(root);

if (findings.length === 0) {
  console.log(`✓ Audyt czystości: ${scanned} plików, 0 markerów do usunięcia.`);
  process.exit(0);
}

console.error(`✖ Audyt czystości: ${findings.length} znalezisk w ${scanned} plikach.\n`);
for (const finding of findings) {
  console.error(`  ${finding.file}:${finding.line}  [${finding.label}] "${finding.match}"`);
}
process.exit(1);
